\begin{theorem}[有限零和博弈的极小极大定理]
\label{thm:game-finite-minimax}
对任意有限收益矩阵\(\bm{M}\)，有
\begin{equation}
  \max_{\bm{x}\in\Delta_m}
  \min_{\bm{y}\in\Delta_n}
  \bm{x}^{\top}\bm{M}\bm{y}
  =
  \min_{\bm{y}\in\Delta_n}
  \max_{\bm{x}\in\Delta_m}
  \bm{x}^{\top}\bm{M}\bm{y}.
  \label{eq:game-minimax-equality}
\end{equation}
共同数值称为博弈值\(v^\star\)。等式两侧的最优解分别称为双方的极小极大策略。
\end{theorem}

